def update(M, level, u, v):
	level[u] = level[v] + 1
	M[u][0] = v
	for j in range(1, 18):
		if M[u][j - 1]:
			M[u][j] = M[M[u][j - 1]][j - 1]

def LCA(M, level, u, v):
	if u == v:
		return u
	if level[u] < level[v]:
		(u, v) = (v, u)
	for i in range(17, -1, -1):
		if M[u][i] and level[M[u][i]] >= level[v]:
			u = M[u][i]
	if u == v:
		return u
	for i in range(17, -1, -1):
		if M[u][i] and M[u][i] != M[v][i]:
			u = M[u][i]
			v = M[v][i]
	return M[u][0]

def distance(par, level, a, b):
	return level[a] + level[b] - 2 * level[LCA(par, level, a, b)]

def solve():
	for _ in range(int(input())):
		N = int(input())
		M = [[0 for _ in range(18)] for _ in range(N + 5)]
		level = [0] * N
		(u, v) = (0, 0)
		results = []
		diameter = 0
		for i in range(1, N):
			p = int(input())
			update(M, level, i, p - 1)
			cur = distance(M, level, i, u)
			if cur > diameter:
				diameter = cur
				v = i
			else:
				cur = distance(M, level, i, v)
				if cur > diameter:
					diameter = cur
					u = i
			results.append(diameter)
		print('\n'.join((str(k) for k in results)))
solve()
